{
  "title": "Discussion about working abroad, language and job search in Europe",
  "topics": [
    {
      "id": "connections-abroad",
      "title": "Connections and people living abroad",
      "claims": [
        {
          "text": "P2 mentions acquaintances @AndriiRaccoon in Austria and walternet134 in Poland",
          "evidence": [3]
        },
        {
          "text": "P3 says they have at least two acquaintances in Austria, one recently arrived and another living there for several years",
          "evidence": [12, 13]
        }
      ]
    },
    {
      "id": "language-requirements",
      "title": "Language requirements in Austria and Slovakia",
      "claims": [
        {
          "text": "German is the main spoken language in Austria, but communication with P3 often happens in English",
          "evidence": [14, 15]
        },
        {
          "text": "95% of vacancies require local language proficiency",
          "evidence": [26]
        },
        {
          "text": "Many candidates are filtered out because they lack language skills",
          "evidence": [27]
        },
        {
          "text": "Some employers accept candidates with low language knowledge",
          "evidence": [29]
        },
        {
          "text": "Employers usually ask for B2 level, sometimes B1, and rarely require a certificate",
          "evidence": [46]
        },
        {
          "text": "P1 has been in Slovakia for almost a year, works in English, neighbors speak Ukrainian",
          "evidence": [43, 44, 45]
        },
        {
          "text": "P3 started learning the local language recently due to daily life discomfort",
          "evidence": [47]
        }
      ]
    },
    {
      "id": "job-search-experience",
      "title": "Finding jobs abroad",
      "claims": [
        {
          "text": "Finding a job abroad is hard but possible; P3 secured a position within two months",
          "evidence": [16, 17]
        },
        {
          "text": "P3 advises using LinkedIn for job hunting",
          "evidence": [18]
        },
        {
          "text": "P3 sent about 100 applications and got only 3 interviews",
          "evidence": [21, 22, 23]
        }
      ]
    },
    {
      "id": "salary-and-education",
      "title": "Salary levels and education relevance",
      "claims": [
        {
          "text": "Salaries in Europe are generally higher than in Ukraine, but often low offers are given",
          "evidence": [35, 37]
        },
        {
          "text": "Higher education rarely influences hiring decisions",
          "evidence": [32]
        }
      ]
    },
    {
      "id": "personal-language-learning",
      "title": "Personal language learning and community",
      "claims": [
        {
          "text": "P3 has been living in Austria since 17.11.2025",
          "evidence": [49]
        },
        {
          "text": "P1 has been in Austria since around 03.09.2025",
          "evidence": [54]
        },
        {
          "text": "P1 experiences language barrier at events, feels English is slightly cringe",
          "evidence": [51, 52]
        },
        {
          "text": "P1 suggests practicing conversational English on Discord channels",
          "evidence": [56, 57]
        },
        {
          "text": "P3 considers moving to Warsaw for a tech event and views Austria as the best European choice, though also considered Ireland, Norway, and Spain",
          "evidence": [59, 60]
        }
      ]
    }
  ],
  "decisions": [],
  "openQuestions": []
}
